    --yellow: #F7C81B;
    --black: #111111;
    --white: #FAFAF7;
    --grey: #D8D8D4;
  }
  * { margin: 0; padding: 0; box-sizing: border-box; }
  html { scroll-behavior: smooth; }
  body {
    font-family: 'Archivo', 'Helvetica Neue', Arial, sans-serif;
    background: var(--white);
    color: var(--black);
    line-height: 1.5;
  }

  /* ---- Mondrian grid layout ---- */
  .grid {
    display: grid;
    grid-template-columns: repeat(12, 1fr);
    grid-auto-rows: minmax(64px, auto);
    gap: 0;
    border-top: 12px solid var(--black);
  }
  .cell {
    border-right: 12px solid var(--black);
    border-bottom: 12px solid var(--black);
    padding: 28px;
    display: flex;
    flex-direction: column;
    justify-content: center;
    gap: 12px;
  }
  .cell:last-child { border-right: none; }
  .no-right { border-right: none; }
  .no-bottom { border-bottom: none; }

  /* ---- Hero ---- */
  .hero {
    grid-column: 1 / 9;
    grid-row: 1 / 4;
    background: var(--white);
    padding: 48px 40px;
    justify-content: flex-start;
  }
  .hero .kicker {
    font-weight: 700;
    font-size: 13px;
    letter-spacing: 0.18em;
    text-transform: uppercase;
  }
  .hero h1 {
    font-weight: 900;
    font-size: clamp(34px, 5vw, 64px);
    line-height: 1.02;
    letter-spacing: -0.02em;
    max-width: 12ch;
  }
  .hero .sub {
    font-size: 18px;
    max-width: 46ch;
    color: #333;
  }

  /* ---- Colour blocks ---- */
  .block-red { grid-column: 9 / 13; grid-row: 1 / 3; background: var(--red); }
  .block-yellow { grid-column: 9 / 13; grid-row: 3 / 4; background: var(--yellow); }

  /* ---- Canvas (the painting) ---- */
  .painting {
    grid-column: 1 / 6;
    grid-row: 4 / 7;
    background: var(--white);
    padding: 0;
  }
  .painting canvas { display: block; width: 100%; height: 100%; }

  /* ---- Facts ---- */
  .facts {
    grid-column: 6 / 13;
    grid-row: 4 / 7;
    background: var(--white);
  }
  .facts h2 {
    font-weight: 900;
    font-size: 22px;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    border-bottom: 4px solid var(--black);
    padding-bottom: 8px;
    margin-bottom: 4px;
  }
  .facts dl { display: grid; grid-template-columns: auto 1fr; gap: 6px 18px; }
  .facts dt { font-weight: 700; font-size: 14px; text-transform: uppercase; letter-spacing: 0.06em; }
  .facts dd { font-size: 15px; }

