  .movement {
    grid-column: 1 / 8;
    grid-row: 7 / 9;
    background: var(--white);
  }
  .movement h2 {
    font-weight: 900;
    font-size: 22px;
    text-transform: uppercase;
    letter-spacing: 0.08em;
  }
  .movement p { font-size: 16px; max-width: 60ch; }
  .movement .principle {
    display: flex;
    gap: 10px;
    align-items: center;
    font-size: 15px;
    font-weight: 500;
  }
  .swatch { width: 18px; height: 18px; border: 2px solid var(--black); flex: none; }

